def solve_quasigroup_bt(n):
    """Solve QG3 quasigroup using backtracking with constraint propagation."""

    # grid[i][j] = value or -1 if unassigned
    grid = [[-1 for _ in range(n)] for _ in range(n)]

    # Pre-assign diagonal
    for i in range(n):
        grid[i][i] = i

    # Track used values in each row and column
    row_used = [set([i]) for i in range(n)]  # diagonal pre-assigned
    col_used = [set([i]) for i in range(n)]  # diagonal pre-assigned

    def get_possible(i, j):
        """Get possible values for cell (i,j)."""
        if grid[i][j] != -1:
            return []
        possible = []
        for v in range(n):
            if v not in row_used[i] and v not in col_used[j]:
                possible.append(v)
        return possible

    def check_qg3(i, j):
        """Check if QG3 constraint is satisfied for (i,j) pair."""
        # x[x[i][j]][x[j][i]] = i
        if grid[i][j] == -1 or grid[j][i] == -1:
            return True
        a, b = grid[i][j], grid[j][i]
        if grid[a][b] == -1:
            return True
        return grid[a][b] == i

    def check_all_qg3():
        """Check all QG3 constraints that can be checked."""
        for i in range(n):
            for j in range(n):
                if not check_qg3(i, j):
                    return False
        return True

    def select_unassigned():
        """Select unassigned cell with fewest possibilities (MRV)."""
        best = None
        best_count = n + 1
        for i in range(n):
            for j in range(n):
                if grid[i][j] == -1:
                    count = len(get_possible(i, j))
                    if count < best_count:
                        best_count = count
                        best = (i, j)
        return best

    def solve():
        cell = select_unassigned()
        if cell is None:
            return True

        i, j = cell
        possible = get_possible(i, j)

        for v in possible:
            # Try assigning v
            grid[i][j] = v
            row_used[i].add(v)
            col_used[j].add(v)

            if check_all_qg3():
                if solve():
                    return True

            # Backtrack
            grid[i][j] = -1
            row_used[i].remove(v)
            col_used[j].remove(v)

        return False

    if solve():
        return grid
    return None

# Test for small n
for n in [2, 3, 4, 5]:
